-- 2. bio-core-lpm-synth
INSERT INTO literature_references (project_id, literaturebase_id, title, authors, year, doi, venue, type, status, notes)
SELECT '28997544-0d87-4b05-9ee2-7c474513c108', 'OE-LITERATURE-neldner-etal-2026-human-uniqueness-of-mind',
  'Children and adults across 15 countries believe in human uniqueness of mind: a cross-cultural investigation of cross-species mind perception', '["Neldner, Karri", "Maurits, Luke", "Junker, Magie", "Abbas, Lara", "Abbas, Nayrouz", "Abis, Arianna", "Amici, Federica", "Arroyo-Garcia, Bernardo", "Asghari, Negar", "Barragán Pardo, Giovanna", "Zhang, Zhen", "Peña Chumacero, Junior", "Dzabatou, Ardain", "Eirdosh, Dustin", "Hanisch, Susan", "Herrnsdorf, Tom", "Hovehne, Tom", "Junker, Alicia", "Kanngiesser, Patricia", "Villa Larens, Felipe", "Mahmoud, Safaa", "Masaquiza, Sandra", "Iino, Masato", "Maulany, Risma Illa", "Meng, Tongtong", "Mutlu, Kardelen", "Ngakan, Putu Oka", "Peközer, Ebru", "Petrović, Ljubica", "Rehatalanit, Mirella Christy", "Piscayanti, Kadek Sonia", "Pope-Caldwell, Sarah", "Sandoval Sernaque, Maria Inés", "Shishala, Dennis", "Sportelli, Doriana", "Stengelin, Roman", "Stodulka, Thomas", "Striegler, Blanca", "Sun, Wanting", "Sunderarajan, Jahnavi", "Tempelmann, Sebastian", "Thajib, Ferdiansyah", "Thiede, Noemi", "Tjizao, Disney", "Useb, Linus", "Woidich, Lena", "Weyrowitz, Janina", "Haun, Daniel", "Liebal, Katja"]'::jsonb, 2026, '10.1016/j.jenvp.2025.102861', 'Journal of Environmental Psychology', 'article', 'accepted',
  'Not a primary source for this project''s "Dichotomized Causal Reasoning (DCR)" theory, but directly relevant to the comparative study''s open empirical question: this 48-author, 15-country study finds that an early-emerging, stable, cross-culturally universal belief -- that human minds are categorically unlike animal minds, even though people readily grant animals thoughts and feelings in a weaker sense -- is already in place in children by the age this project''s own K-12 progression begins. Bio-Core deliberately keeps biology''s causal-reasoning content dichotomized from cognition as a cross-domain example (no Theory-of-Mind or animal/computer-mind transfer target exists in this project''s vocabulary), so its design never has to confront or dislodge this exceptionalism belief directly. This paper shows that choice is a real simplification with a real cost, not a neutral default: the belief it avoids engaging is universal and early-forming, not something students simply lack an opinion about, and it is the same presence-of-mind-vs-human-likeness distinction the paper''s own two-part measure isolates.'
WHERE NOT EXISTS (SELECT 1 FROM literature_references WHERE project_id = '28997544-0d87-4b05-9ee2-7c474513c108' AND literaturebase_id = 'OE-LITERATURE-neldner-etal-2026-human-uniqueness-of-mind');

-- 3. interdisciplinary-lpm-synth
INSERT INTO literature_references (project_id, literaturebase_id, title, authors, year, doi, venue, type, status, notes)
SELECT '371fce26-d1f3-439b-95df-0a0e38b8a824', 'OE-LITERATURE-neldner-etal-2026-human-uniqueness-of-mind',
  'Children and adults across 15 countries believe in human uniqueness of mind: a cross-cultural investigation of cross-species mind perception', '["Neldner, Karri", "Maurits, Luke", "Junker, Magie", "Abbas, Lara", "Abbas, Nayrouz", "Abis, Arianna", "Amici, Federica", "Arroyo-Garcia, Bernardo", "Asghari, Negar", "Barragán Pardo, Giovanna", "Zhang, Zhen", "Peña Chumacero, Junior", "Dzabatou, Ardain", "Eirdosh, Dustin", "Hanisch, Susan", "Herrnsdorf, Tom", "Hovehne, Tom", "Junker, Alicia", "Kanngiesser, Patricia", "Villa Larens, Felipe", "Mahmoud, Safaa", "Masaquiza, Sandra", "Iino, Masato", "Maulany, Risma Illa", "Meng, Tongtong", "Mutlu, Kardelen", "Ngakan, Putu Oka", "Peközer, Ebru", "Petrović, Ljubica", "Rehatalanit, Mirella Christy", "Piscayanti, Kadek Sonia", "Pope-Caldwell, Sarah", "Sandoval Sernaque, Maria Inés", "Shishala, Dennis", "Sportelli, Doriana", "Stengelin, Roman", "Stodulka, Thomas", "Striegler, Blanca", "Sun, Wanting", "Sunderarajan, Jahnavi", "Tempelmann, Sebastian", "Thajib, Ferdiansyah", "Thiede, Noemi", "Tjizao, Disney", "Useb, Linus", "Woidich, Lena", "Weyrowitz, Janina", "Haun, Daniel", "Liebal, Katja"]'::jsonb, 2026, '10.1016/j.jenvp.2025.102861', 'Journal of Environmental Psychology', 'article', 'accepted',
  'Not a primary source for this project''s "Integrated / Contextually Flexible Causal Reasoning (ICR/CFCR)" theory, but a direct empirical check on one of its real instantiations: this project''s own ConceptBase vocabulary already uses Theory of Mind, Distributed Cognition, and Decentralized Causal Reasoning as domain-transfer targets, generalizing the same agency/decentralization reasoning tools from biology to cognition and computation (ant colonies, traffic jams, bird flocks, animal and human minds alike). This 2026, 15-country study finds that the specific boundary this project''s cognition-as-domain-example design has to cross -- treating an animal''s or a computer''s mind as continuous with a human''s -- runs directly against an early-emerging, stable, cross-culturally universal belief in human mental exceptionalism, even though people readily grant animals thoughts and feelings in a weaker sense. The paper''s own two-part measure (whether a mind is present at all, versus whether it resembles a human mind) gives this project''s cognition-as-domain-example design a concrete, evidence-based scaffold: start from where the belief is already permissive (presence), name the human/animal/machine-mind boundary explicitly, then treat "is it humanlike" as the actual target misconception to work against, rather than assuming students will casually generalize decentralized/agency reasoning across human, animal, and computational minds.'
WHERE NOT EXISTS (SELECT 1 FROM literature_references WHERE project_id = '371fce26-d1f3-439b-95df-0a0e38b8a824' AND literaturebase_id = 'OE-LITERATURE-neldner-etal-2026-human-uniqueness-of-mind');
